465			}
466			if p := e.Progress; p != nil {
467				if !selected(st, p.Project) || p.WindowStart.IsZero() {
468					return errors.New("progress requires selected project and requested window")
469				}
470				key := e.RunID + ":" + p.Project
471				prior, ok := st.Runs[key]
472				if ok && !prior.WindowStart.Equal(p.WindowStart) {
473					return errors.New("run window cannot change")
474				}
475				merged := map[string]Page{}
476				seenIssues := map[string]bool{}
477				for _, id := range st.RunIssues[key] {
478					seenIssues[id] = true
479				}
480				for _, id := range prior.IssueIDs {
481					seenIssues[id] = true
482				}
483				for id := range prior.Comments {
484					seenIssues[id] = true
485				}
486				for _, r := range e.Records {
487					if r.Kind == "issue" && r.Project == p.Project {
488						seenIssues[r.ID] = true
489					}
490				}
491				for _, id := range p.IssueIDs {
492					seenIssues[id] = true
493				}
494				for k, v := range prior.Comments {
495					merged[k] = v
496				}
497				for k, v := range p.Comments {
498					if !uuid.MatchString(k) || v.Complete && v.Cursor != "" {
499						return errors.New("invalid comment pagination")
500					}
501					if prev, ok := merged[k]; ok && prev.Complete && !v.Complete {
502						return errors.New("comment pagination cannot regress")
503					}
504					merged[k] = v
505				}
506				p.Comments = merged
507				for id := range merged {
508					seenIssues[id] = true
509				}
510				p.IssueIDs = nil
511				for id := range seenIssues {
512					r, ok := st.Snapshots[st.Current["issue:"+e.Workspace+":issue:"+id]]
513					if !uuid.MatchString(id) || !ok || r.Project != p.Project {
514						return errors.New("pagination issue missing or outside project")
515					}
516					p.IssueIDs = append(p.IssueIDs, id)
517				}
518				sort.Strings(p.IssueIDs)
519				if p.Issues.Complete && p.Issues.Cursor != "" || prior.Issues.Complete && !p.Issues.Complete {
520					return errors.New("invalid issue pagination")
521				}
522				if p.Complete {
523					if !p.Issues.Complete || len(st.RunConflicts[key]) > 0 {
524						return errors.New("cannot complete unfinished or conflicting import")
525					}
526					for _, id := range p.IssueIDs {
527						if !p.Comments[id].Complete {
528							return errors.New("cannot complete before comment pagination finishes")
529						}
530					}
531				}
532				st.Runs[key] = *p
533			}
534			st.Batches[batch] = digest
535			if st.BatchProjects == nil {
536				st.BatchProjects = map[string][]string{}
537			}
538			projects := map[string]bool{}
539			for _, r := range e.Records {
540				projects[r.Project] = true
541			}
542			if e.Progress != nil {
543				projects[e.Progress.Project] = true
544			}
545			for p := range projects {
546				st.BatchProjects[batch] = append(st.BatchProjects[batch], p)
547			}
548			sort.Strings(st.BatchProjects[batch])
549			return nil
550		})
551		return
552	}
553	func visible(st *State, r Record) bool {
554		if !visibleRecord(st, r) {
555			return false
556		}
557		if r.Kind != "comment" {
558			return true
559		}
560		// Parent identity is typed: a comment must resolve directly to an issue.
561		// Do not traverse arbitrary parent chains, even in malformed in-memory state.
562		parentKey := "issue:" + r.Workspace + ":issue:" + r.Issue
563		p, ok := st.Snapshots[st.Current[parentKey]]
564		return ok && p.Kind == "issue" && p.Key() == parentKey && p.Project == r.Project && visibleRecord(st, p)
565	}
566	
567	// visibleRecord checks only the record, its current revision and its project;
568	// it never follows a comment parent or calls visible.
569	func visibleRecord(st *State, r Record) bool {
570		if !selected(st, r.Project) || r.Availability == "deleted" || r.Availability == "inaccessible" {
571			return false
572		}
573		if r.Kind != "project" {
574			p, ok := st.Snapshots[st.Current["issue:"+r.Workspace+":project:"+r.Project]]
575			if ok && (p.Availability == "deleted" || p.Availability == "inaccessible") {
576				return false
577			}
578		}
579		current, ok := st.Snapshots[st.Current[r.Key()]]
580		if !ok || current.Key() != r.Key() || !selected(st, current.Project) || current.Availability == "deleted" || current.Availability == "inaccessible" {
581			return false
582		}
583		return true
584	}
585	func (s Store) Records() ([]Snapshot, error) {
586		st, err := s.Load()
587		if err != nil {
588			return nil, err
589		}
590		out := []Snapshot{}
591		for _, ref := range st.Current {
592			r := st.Snapshots[ref]
593			if visible(&st, r) {
594				out = append(out, snapshotFor(&st, r, ref))
595			}
596		}
597		sort.Slice(out, func(i, j int) bool { return out[i].Key() < out[j].Key() })
598		return out, nil
599	}
600	func (s Store) Get(id string) (Snapshot, bool, error) {
601		st, err := s.Load()
602		if err != nil {
603			return Snapshot{}, false, err
604		}
605		ref := id
606		if !strings.Contains(id, "@") {
607			ref = st.Current[id]
608		}
609		r, ok := st.Snapshots[ref]
610		if !ok || !visible(&st, r) {
611			return Snapshot{}, false, nil
612		}
613		return snapshotFor(&st, r, ref), true, nil
614	}
615	
616	func snapshotFor(st *State, r Record, ref string) Snapshot {
617		result := Snapshot{Record: r, Hash: r.ContentHash(), Ref: ref}
618		coverage := map[string]bool{}
619		for _, run := range st.Runs {
620			if run.Project != r.Project {
621				continue
622			}
623			if !run.Complete {
624				coverage["Project import has unfinished pagination; absence is not evidence of deletion."] = true
625			}
626			for _, v := range run.Limitations {
627				coverage[v] = true
628			}
629		}
630		for v := range coverage {
631			result.Coverage = append(result.Coverage, v)
632		}
633		sort.Strings(result.Coverage)
634		return result
635	}
636	func (s Store) Resolve(value string) (Snapshot, error) {
637		rs, err := s.Records()
638		if err != nil {
639			return Snapshot{}, err
640		}
641		var out []Snapshot
642		for _, r := range rs {
643			if r.Kind == "issue" && (strings.EqualFold(r.Alias, value) || r.URL == value || r.ID == value || r.Key() == value) {
644				out = append(out, r)
645			}
646		}
647		if len(out) != 1 {
648			return Snapshot{}, fmt.Errorf("issue %q resolved to %d records in selected projects", value, len(out))
649		}
650		return out[0], nil
651	}
652	func (s Store) Link(l Link) error {
653		return s.mutate(func(st *State) error {
654			r, ok := st.Snapshots[st.Current[l.Issue]]
655			if !ok || r.Kind != "issue" || !visible(st, r) {
656				return errors.New("link requires a visible issue evidence ID")
657			}
658			switch l.Kind {
659			case "session", "checkpoint", "commit", "pr":
660			default:
661				return errors.New("invalid link kind")
662			}
663			if strings.TrimSpace(l.Value) == "" {
664				return errors.New("link value required")
665			}
666			for _, old := range st.Links {
667				if old == l {
668					return nil
669				}
670			}
671			st.Links = append(st.Links, l)
672			return nil
673		})
674	}
675	func (s Store) Operation(op Operation) error {
676		if !uuid.MatchString(op.ID) || !hashPattern.MatchString(op.PayloadHash) || op.ObservedAt.IsZero() {
677			return errors.New("operation UUID, SHA256 payload hash and observation required")
678		}
679		switch op.Action {
680		case "create", "comment", "status", "assignee", "priority", "labels", "project":
681		default:
682			return errors.New("unsupported operation action")
683		}
684		switch op.Outcome {
685		case "pending", "succeeded", "failed", "unknown":
686		default:
687			return errors.New("invalid operation outcome")
688		}
689		return s.mutate(func(st *State) error {
690			history := st.Operations[op.ID]
691			if len(history) == 0 {
692				if op.Outcome != "pending" {
693					return errors.New("operation must start pending")
694				}
695				if op.Action == "create" {
696					if !selected(st, op.Target) {
697						return errors.New("create target must be selected project UUID")
698					}
699				} else {
700					r, ok := st.Snapshots[st.Current[op.Target]]
701					if !ok || r.Kind != "issue" || !visible(st, r) {
702						return errors.New("operation target must be a visible issue ID")
703					}
704				}
705			} else {
706				prev := history[len(history)-1]
707				beforeChanged := len(prev.Before) != len(op.Before) ||
708					(len(prev.Before) > 0 && !bytes.Equal(canonicalJSON(prev.Before), canonicalJSON(op.Before)))
709				if prev.Target != op.Target || prev.Action != op.Action || prev.PayloadHash != op.PayloadHash || beforeChanged {
710					return errors.New("operation intent cannot change")
711				}
712				a, _ := json.Marshal(prev)
713				b, _ := json.Marshal(op)
714				if bytes.Equal(a, b) {
715					return nil
716				}
717				if prev.Outcome == "succeeded" || prev.Outcome == "failed" || op.Outcome == "pending" || op.ObservedAt.Before(prev.ObservedAt) {
718					return errors.New("invalid operation transition")
719				}
720			}
721			if op.Outcome == "succeeded" && (op.ObjectID == "" || op.URL == "") {
722				return errors.New("success requires returned object ID and URL")
723			}
724			st.Operations[op.ID] = append(history, op)
725			return nil
726		})
727	}
728	func (s Store) Disconnect(project string, purge bool) error {
729		if !uuid.MatchString(project) {
730			return errors.New("project UUID required")
731		}
732		return s.mutate(func(st *State) error {
733			if st.Binding.Version != 1 {
734				return errors.New("issue store is not configured")
735			}
736			ps := []string{}
737			for _, p := range st.Binding.Projects {
738				if p != project {
739					ps = append(ps, p)
740				}
741			}
742			st.Binding.Projects = ps
743			if purge {
744				removed := map[string]bool{}
745				for ref, r := range st.Snapshots {
746					if r.Project == project {
747						removed[r.Key()] = true
748						delete(st.Snapshots, ref)
749					}
750				}
751				for key, ref := range st.Current {
752					if _, ok := st.Snapshots[ref]; !ok {
753						delete(st.Current, key)
754					}
755				}
756				links := st.Links[:0]
757				for _, l := range st.Links {
758					if !removed[l.Issue] {
759						links = append(links, l)
760					}
761				}
762				st.Links = links
763				for id, ops := range st.Operations {
764					if len(ops) > 0 && (removed[ops[0].Target] || ops[0].Target == project) {
765						delete(st.Operations, id)
766					}
767				}
768				for id, p := range st.Runs {
769					if p.Project == project {
770						delete(st.Runs, id)
771					}
772				}
773				for key := range st.RunIssues {
774					if strings.HasSuffix(key, ":"+project) {
775						delete(st.RunIssues, key)
776					}
777				}
778				for key := range st.RunConflicts {
779					if strings.HasSuffix(key, ":"+project) {
780						delete(st.RunConflicts, key)
781					}
782				}
783				for batch := range st.Batches {
784					projects, known := st.BatchProjects[batch]
785					remove := !known
786					for _, p := range projects {
787						if p == project {
788							remove = true
789						}
790					}
791					if remove {
792						delete(st.Batches, batch)
793						delete(st.BatchProjects, batch)
794					}
795				}
796				if s.CleanDerived != nil {
797					return s.CleanDerived()
798				}
799			}
800			return nil
801		})
802	}
