804	type Status struct {
805		Binding     Binding                `json:"binding"`
806		Records     int                    `json:"records"`
807		Stale       int                    `json:"stale"`
808		Incomplete  int                    `json:"incomplete"`
809		PendingRuns int                    `json:"pending_runs"`
810		LimitedRuns int                    `json:"limited_runs"`
811		Runs        map[string]Progress    `json:"runs,omitempty"`
812		Links       []Link                 `json:"links,omitempty"`
813		Operations  map[string][]Operation `json:"operations,omitempty"`
814	}
815	
816	func (s Store) Status(now time.Time) (Status, error) {
817		st, err := s.Load()
818		if err != nil {
819			return Status{}, err
820		}
821		out := Status{Binding: st.Binding, Runs: st.Runs, Links: st.Links, Operations: st.Operations}
822		for _, run := range st.Runs {
823			if !selected(&st, run.Project) {
824				continue
825			}
826			if !run.Complete {
827				out.PendingRuns++
828			}
829			if len(run.Limitations) > 0 {
830				out.LimitedRuns++
831			}
832		}
833		for _, ref := range st.Current {
834			r := st.Snapshots[ref]
835			if !visible(&st, r) {
836				continue
837			}
838			out.Records++
839			if now.Sub(r.ObservedAt) > 24*time.Hour {
840				out.Stale++
841			}
842			if len(r.Completeness.Missing)+len(r.Completeness.Truncated)+len(r.Completeness.Limitations) > 0 {
843				out.Incomplete++
844			}
845		}
846		return out, nil
847	}
