6		"bytes"
7		"crypto/sha256"
8		"encoding/hex"
9		"encoding/json"
10		"errors"
11		"fmt"
12		"io"
13		"net/url"
14		"os"
15		"path/filepath"
16		"regexp"
17		"sort"
18		"strings"
19		"time"
20	)
21	
22	const MaxBatchBytes = 2 << 20
23	const MaxRecords = 100
24	
25	var uuid = regexp.MustCompile(`^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$`)
26	var hashPattern = regexp.MustCompile(`^[0-9a-f]{64}$`)
27	
28	type Binding struct {
29		Version       int      `json:"version"`
30		Provider      string   `json:"provider"`
31		Workspace     string   `json:"workspace"`
32		WorkspaceName string   `json:"workspace_name,omitempty"`
33		Projects      []string `json:"projects"`
34	}
35	type Completeness struct {
36		Missing     []string `json:"missing,omitempty"`
37		Truncated   []string `json:"truncated,omitempty"`
38		Limitations []string `json:"limitations,omitempty"`
39	}
40	type Record struct {
41		Kind         string                     `json:"kind"`
42		Workspace    string                     `json:"workspace"`
43		ID           string                     `json:"id"`
44		Project      string                     `json:"project"`
45		Issue        string                     `json:"issue,omitempty"`
46		Alias        string                     `json:"alias,omitempty"`
47		URL          string                     `json:"url"`
48		Title        string                     `json:"title,omitempty"`
49		Text         string                     `json:"text"`
50		Fields       map[string]json.RawMessage `json:"fields,omitempty"`
51		UpdatedAt    time.Time                  `json:"updated_at"`
52		ObservedAt   time.Time                  `json:"observed_at"`
53		Completeness Completeness               `json:"completeness"`
54		// Only an explicit remote observation may set deleted or inaccessible.
55		Availability string `json:"availability,omitempty"`
