57	
58	func (r Record) Key() string { return "issue:" + r.Workspace + ":" + r.Kind + ":" + r.ID }
59	func (r Record) Group() string {
60		if r.Kind == "comment" {
61			return r.Workspace + ":" + r.Issue
62		}
63		return r.Workspace + ":" + r.ID
64	}
65	func Hash(data []byte) string { h := sha256.Sum256(data); return hex.EncodeToString(h[:]) }
66	
67	// Normalize nested RawMessage objects too, so CLI JSON and MCP's decoded
68	// object transport agree despite object-key ordering or insignificant spaces.
69	func canonicalJSON(value any) []byte {
70		b, _ := json.Marshal(value)
71		d := json.NewDecoder(bytes.NewReader(b))
72		d.UseNumber()
73		var normalized any
74		_ = d.Decode(&normalized)
75		out, _ := json.Marshal(normalized)
76		return out
77	}
78	func (r Record) ContentHash() string {
79		r.ObservedAt = time.Time{}
80		// Accessibility is a local observation of this source revision. Remote
81		// deletion/access denial often does not provide a new source update time.
82		r.Availability = ""
83		return Hash(canonicalJSON(r))
84	}
