141		// RunConflicts keeps unresolved equal-timestamp conflicts per run and
142		// project, so a later batch cannot complete a run an earlier batch left
143		// serving stale evidence.
144		RunConflicts map[string][]string `json:"run_conflicts,omitempty"`
145	}
146	
147	// The adapter supplies Brain's cross-process lock and platform-specific atomic
148	// writer. All durable state is published by one replacement while holding it.
149	type Store struct {
150		Root         string
151		Lock         func(func() error) error
152		Write        func(string, []byte) error
153		Read         func(string) ([]byte, error)
154		CleanDerived func() error
155	}
156	
157	func (s Store) Load() (State, error) {
158		st := State{Current: map[string]string{}, Snapshots: map[string]Record{}, Batches: map[string]string{}, Runs: map[string]Progress{}, Operations: map[string][]Operation{}}
159		read := s.Read
160		if read == nil {
161			read = os.ReadFile
162		}
163		b, err := read(filepath.Join(s.Root, "state.json"))
164		if os.IsNotExist(err) {
165			return st, nil
166		}
167		if err != nil {
168			return st, err
169		}
170		err = json.Unmarshal(b, &st)
171		if st.BatchProjects == nil {
172			st.BatchProjects = map[string][]string{}
173		}
174		if err == nil && (st.Current == nil || st.Snapshots == nil || st.Batches == nil || st.Runs == nil || st.Operations == nil || st.Binding.Version != 1) {
175			err = errors.New("invalid issue state")
176		}
177		if err == nil {
178			for ref, r := range st.Snapshots {
179				raw, _ := json.Marshal(r)
180				if validRecord(r) != nil || ref != r.Key()+"@"+Hash(raw) || r.Workspace != st.Binding.Workspace {
181					return st, errors.New("issue snapshot integrity failure")
182				}
183			}
184			for key, ref := range st.Current {
185				r, ok := st.Snapshots[ref]
186				if !ok || key != r.Key() {
187					return st, errors.New("issue current pointer integrity failure")
188				}
189			}
190		}
191		return st, err
192	}
193	func (s Store) mutate(fn func(*State) error) error {
194		if s.Lock == nil || s.Write == nil {
195			return errors.New("issue mutations require lock and atomic writer")
196		}
197		return s.Lock(func() error {
198			st, err := s.Load()
199			if err != nil {
200				return err
201			}
202			if err = fn(&st); err != nil {
203				return err
204			}
205			b, err := json.Marshal(st)
206			if err != nil {
207				return err
208			}
209			return s.Write(filepath.Join(s.Root, "state.json"), b)
210		})
211	}
212	func Decode(data []byte, out any) error {
213		if len(data) > MaxBatchBytes {
214			return errors.New("issue input exceeds 2 MiB")
215		}
216		d := json.NewDecoder(bytes.NewReader(data))
217		d.DisallowUnknownFields()
218		if err := d.Decode(out); err != nil {
219			return err
220		}
221		var extra any
222		if err := d.Decode(&extra); err != io.EOF {
223			return errors.New("expected exactly one JSON value")
224		}
225		return nil
226	}
227	func selected(st *State, p string) bool {
228		for _, v := range st.Binding.Projects {
229			if v == p {
230				return true
231			}
232		}
233		return false
234	}
235	func (s Store) Configure(b Binding) error {
236		if b.Version != 1 || b.Provider == "" || !uuid.MatchString(b.Workspace) {
237			return errors.New("version 1, provider and workspace UUID required")
238		}
239		seen := map[string]bool{}
240		for _, p := range b.Projects {
241			if !uuid.MatchString(p) || seen[p] {
242				return errors.New("projects must be unique UUIDs")
243			}
244			seen[p] = true
245		}
246		return s.mutate(func(st *State) error {
247			if st.Binding.Workspace != "" && (st.Binding.Workspace != b.Workspace || st.Binding.Provider != b.Provider) {
248				return errors.New("repository already bound to another workspace/provider")
249			}
250			st.Binding = b
251			return nil
252		})
253	}
254	func validRecord(r Record) error {
255		if !uuid.MatchString(r.ID) || !uuid.MatchString(r.Workspace) || !uuid.MatchString(r.Project) {
256			return errors.New("record identities must be UUIDs")
257		}
258		switch r.Kind {
259		case "project":
260			if r.ID != r.Project {

260			if r.ID != r.Project {
261				return errors.New("project identity mismatch")
262			}
263		case "issue":
264		case "comment":
265			if !uuid.MatchString(r.Issue) {
266				return errors.New("comment requires issue UUID")
267			}
268		default:
269			return errors.New("unknown record kind")
270		}
271		if r.Kind != "comment" && r.Issue != "" {
272			return errors.New("only comments have an issue parent")
273		}
274		if r.UpdatedAt.IsZero() || r.ObservedAt.IsZero() {
275			return errors.New("record timestamps required")
276		}
277		u, err := url.Parse(r.URL)
278		if err != nil || u.Scheme != "https" || u.Host == "" {
279			return errors.New("canonical HTTPS URL required")
280		}
281		if r.Availability != "" && r.Availability != "available" && r.Availability != "deleted" && r.Availability != "inaccessible" {
282			return errors.New("invalid availability")
283		}
284		return nil
285	}
