287	type ImportResult struct {
288		Imported  int      `json:"imported"`
289		Ignored   int      `json:"ignored"`
290		Conflicts []string `json:"conflicts,omitempty"`
291		Replay    bool     `json:"replay"`
292	}
293	
294	func contains(values []string, value string) bool {
295		for _, v := range values {
296			if v == value {
297				return true
298			}
299		}
300		return false
301	}
302	
303	// Equal source timestamps may acquire better observations, but must not
304	// overwrite fields previously observed in full. Parent project membership is
305	// validated separately: moving an issue does not edit its comments remotely.
306	func compatibleObservation(old, next Record) bool {
307		canComplete := func(names ...string) bool {
308			incomplete := false
309			for _, name := range names {
310				if contains(next.Completeness.Missing, name) || contains(next.Completeness.Truncated, name) {
311					return false
312				}
313				incomplete = incomplete || contains(old.Completeness.Missing, name) || contains(old.Completeness.Truncated, name)
314			}
315			return incomplete
316		}
317		completeText := func(before, after string, names ...string) string {
318			if !canComplete(names...) {
319				return before
320			}
321			// Providers may add ellipses or truncation notices; the available text
322			// need not be a literal prefix of the complete field.
323			return after
324		}
325		old.Text = completeText(old.Text, next.Text, "text", "description", "body")
326		old.Title = completeText(old.Title, next.Title, "title")
327		old.Alias = completeText(old.Alias, next.Alias, "alias", "identifier")
328		old.URL = completeText(old.URL, next.URL, "url", "comment_url")
329		fields := make(map[string]json.RawMessage, len(old.Fields))
330		for key, value := range old.Fields {
331			fields[key] = value
332		}
333		for key, value := range next.Fields {
334			if canComplete("fields", key, "fields."+key) {
335				fields[key] = value
336			}
337		}
338		old.Fields = fields
339		if old.Kind == "comment" {
340			old.Project = next.Project
341		}
342		old.Completeness = next.Completeness
343		return old.ContentHash() == next.ContentHash()
344	}
