191	// Continuations are addressable IDs, so CLI/MCP get, multi-get and workspace
192	// get all share the same pagination contract without host-specific arguments.
193	const issueEvidencePageBytes = 8 * 1024
194	const issuePageMarker = "#offset="
195	
196	func getIssueEvidence(brainDir, id string) (unifiedResult, bool, error) {
197		ref, cursor, paged := strings.Cut(id, issuePageMarker)
198		offset := 0
199		if paged {
200			var err error
201			offset, err = strconv.Atoi(cursor)
202			if err != nil || offset < 0 || !strings.Contains(ref, "@") {
203				return unifiedResult{}, false, errors.New("issue continuation requires an exact snapshot and nonnegative byte offset")
204			}
205		}
206		s, ok, err := issueStore(brainDir).Get(ref)
207		if paged && err == nil && !ok {
208			return unifiedResult{}, false, errors.New("issue continuation requires an existing exact snapshot")
209		}
210		if err != nil || !ok {
211			return unifiedResult{}, ok, err
212		}
213		r := issueUnified(s)
214		if offset > len(r.Text) || offset < len(r.Text) && !utf8.RuneStart(r.Text[offset]) {
215			return unifiedResult{}, false, errors.New("issue offset is outside evidence or splits a UTF-8 character")
216		}
217		if paged || len(r.Text) > issueEvidencePageBytes {
218			r.Issue.Offset = offset
219			r.Issue.TotalBytes = len(r.Text)
220			page, _ := truncateUTF8Bytes(r.Text[offset:], issueEvidencePageBytes)
221			end := offset + len(page)
222			if end < len(r.Text) {
223				r.Issue.NextID = s.Ref + issuePageMarker + strconv.Itoa(end)
224			}
225			r.Text = page
226			r.Truncated = offset != 0 || end < r.Issue.TotalBytes
227			if paged {
228				r.ID = id
229			}
230		}
231		return r, true, nil
232	}
