262	func retrieveIssues(brainDir, query string, limit int) ([]unifiedResult, error) {
263		records, err := issueStore(brainDir).Records()
264		if err != nil {
265			return nil, err
266		}
267		if len(records) == 0 {
268			return nil, nil
269		}
270		idx := docIndex{}
271		byID := map[string]issues.Snapshot{}
272		fingerprint := ""
273		for _, r := range records {
274			byID[r.Key()] = r
275			fingerprint += r.Ref
276			idx.Records = append(idx.Records, docRecord{ID: r.Key(), Path: r.URL, Heading: r.Alias + " " + r.Title, Text: issueUnified(r).Text})
277		}
278		// Stable content-derived generation prevents same-count updates reusing FTS.
279		digest := issues.Hash([]byte(fingerprint))
280		var stamp int64
281		for _, c := range []byte(digest[:15]) {
282			stamp = stamp*17 + int64(c)
283		}
284		idx.GeneratedAt = time.Unix(0, stamp)
285		var ranked []scoredDocRecord
286		var ok bool
287		_ = withBrainWriteLock(brainDir, func() error {
288			current, err := issueStore(brainDir).Records()
289			if err != nil {
290				return err
291			}
292			if len(current) != len(records) {
293				return nil
294			}
295			for i := range records {
296				if records[i].Ref != current[i].Ref {
297					return nil
298				}
299			}
300			if err := rejectExistingSymlinkPathComponents(brainDir, "issues/derived"); err != nil {
301				return err
302			}
303			ranked, ok = rankDocsViaFTS(filepath.Join(brainDir, "issues", "derived"), idx, query, len(records))
304			return nil
305		})
306		if !ok {
307			ranked = rankDocsLexical(idx, query, len(records))
308		}
309		var list []unifiedResult
310		for _, hit := range ranked {
311			list = append(list, issueUnified(byID[hit.Record.ID]))
312		}
313		merged := rrfMergeUnified([][]unifiedResult{list}, len(records))
314		beforeIssueRankingCurrencyCheck()
315		// Ranking can overlap a disconnect. Never return candidates that ceased
316		// to be current and visible while ranking ran.
317		current, err := issueStore(brainDir).Records()
318		if err != nil {
319			return nil, err
320		}
321		allowed := map[string]bool{}
322		for _, r := range current {
323			allowed[r.Ref] = true
324		}
325		out := []unifiedResult{}
326		groups := map[string]bool{}
327		for _, r := range merged {
328			if !allowed[r.Issue.Snapshot] {
329				continue
330			}
331			g := byID[r.ID].Group()
332			if groups[g] {
333				continue
334			}
335			groups[g] = true
336			r.Truncated = len(r.Text) > 1800
337			r.Text = boundedIssueText(r.Text, 1800)
338			out = append(out, r)
339			if len(out) >= limit {
340				break
341			}
342		}
343		return out, nil
344	}
