380			out := []unifiedResult{*pinned}
381			for _, h := range hits {
382				if h.ID != pinned.ID && len(out) < min(limit, 3) {
383					out = append(out, h)
384				}
385			}
386			hits = out
387		}
388		return task, hits, nil
